def run(self, prediction, callback_url, callback_token, disable_callback):
    from queue import Empty, Full
    from threading import Thread
    from urllib.parse import urlparse
    import requests

    if disable_callback or not prediction.get("frame_sequence"):
        return {"queued": False}
    if urlparse(callback_url).scheme != "https" or not callback_token:
        raise ValueError("An authenticated HTTPS callback is required")
    state = self._init_results

    def deliver():
        # One persistent connection per worker avoids a TLS handshake per gaze.
        # Two in-flight requests and one replaceable pending result bound work
        # during network stalls. The receiver rejects reordered sequences.
        with requests.Session() as http:
            while True:
                try:
                    url, token, result = state["pending"].get(timeout=30)
                except Empty:
                    return
                try:
                    http.post(url, json={"prediction": result}, headers={"X-Pong-Webhook-Key": token},
                              timeout=(1, 1), allow_redirects=False)
                except requests.RequestException:
                    pass  # Never retry obsolete gaze; the next fresh frame replaces it.

    with state["lock"]:
        workers = [worker for worker in state["workers"] if worker.is_alive()]
        while len(workers) < 2:
            worker = Thread(target=deliver, daemon=True, name="gaze-callback")
            worker.start()
            workers.append(worker)
        state["workers"] = workers
        try:
            state["pending"].get_nowait()
        except Empty:
            pass
        state["pending"].put_nowait((callback_url, callback_token, prediction))
    return {"queued": True}
